#!/bin/bash
# recenv.sh "RECIPE OPTIONS" : print the engine environment that `recipe.sh start` would hand to the container for these options
# (NAME=value lines: every TENSORFOLD_* / TF_FLASHNEXT_* variable, KV_DTYPE, PARALLEL), i.e. recipe.sh's exports + MiaAI config.sh's
# defaults for what recipe.sh leaves unset. Nothing is started. HEAD2FILE = a present head2 file (so the HEAD2 branch is taken).
D=$(cd "$(dirname "$0")" && pwd); T=$(mktemp -d); mkdir -p $T/hf/q38
[ -s "${HEAD2FILE:-/nonexistent}" ] && ln -s "$HEAD2FILE" $T/hf/q38/head2_r9.bin
awk '/^case "\$\{1:-\}" in/{exit} {print}' $D/recipe.sh > $T/r.sh
cat >> $T/r.sh <<'EOF'
PARALLEL="${PARALLEL:-5}"
export TF_FLASHNEXT_DRAFTS="${TF_FLASHNEXT_DRAFTS:-6}" TF_FLASHNEXT_SAMPLED_HEADS="${TF_FLASHNEXT_SAMPLED_HEADS:-1}" TF_FLASHNEXT_SAMPLE_CAND="${TF_FLASHNEXT_SAMPLE_CAND:-1}"
export TF_FLASHNEXT_GATHER_EARLY="${TF_FLASHNEXT_GATHER_EARLY:-1}" TF_FLASHNEXT_HOST_DRAW_THREADS="${TF_FLASHNEXT_HOST_DRAW_THREADS:-7}" TF_FLASHNEXT_KEEP_LATE="${TF_FLASHNEXT_KEEP_LATE:-1}"
export TF_FLASHNEXT_GATHER_READ="${TF_FLASHNEXT_GATHER_READ:-pread}" TF_FLASHNEXT_DRAFT_AHEAD="${TF_FLASHNEXT_DRAFT_AHEAD:-1}" TF_FLASHNEXT_WARM_AHEAD="${TF_FLASHNEXT_WARM_AHEAD:-1}"
export TF_FLASHNEXT_PREFILL_TAIL="${TF_FLASHNEXT_PREFILL_TAIL:-512}" TF_FLASHNEXT_PROMPT_HC2="${TF_FLASHNEXT_PROMPT_HC2:-1}" TF_FLASHNEXT_PROMPT_SHARED_DIRECT="${TF_FLASHNEXT_PROMPT_SHARED_DIRECT:-1}"
export TF_FLASHNEXT_PROMPT_EXPERT_TILE_ROWS="${TF_FLASHNEXT_PROMPT_EXPERT_TILE_ROWS:-256}" TF_FLASHNEXT_HEAD_PIECE="${TF_FLASHNEXT_HEAD_PIECE:-1536}" TF_FLASHNEXT_PROMPT_GEMM2="${TF_FLASHNEXT_PROMPT_GEMM2:-1}"
export TF_FLASHNEXT_SHARED_SIDE="${TF_FLASHNEXT_SHARED_SIDE:-1}" TF_FLASHNEXT_GDN_LANES="${TF_FLASHNEXT_GDN_LANES:-1}" TF_FLASHNEXT_CONFIDENCE="${TF_FLASHNEXT_CONFIDENCE:--0.4}"
export TF_FLASHNEXT_PRODUCT_STREAMS="${TF_FLASHNEXT_PRODUCT_STREAMS:-5}" TENSORFOLD_NO_UPDATE_CHECK=1 TENSORFOLD_MEMORY_RESERVE_GIB="${TENSORFOLD_MEMORY_RESERVE_GIB:-9}"
export KV_DTYPE PARALLEL
EOF
env -i PATH="$PATH" HOME="$HOME" HF_CACHE=$T/hf $1 bash -c "set -- start; source $T/r.sh >/dev/null; env" | grep -E '^(TENSORFOLD|TF_FLASHNEXT)_[A-Z0-9_]+=|^KV_DTYPE=|^PARALLEL=' | sort
rc=${PIPESTATUS[0]}; rm -rf $T; exit $rc
